let intervalId;
        let isBoxMode = false;
        const colors = ['#ff0000', '#00ff00', '#0000ff', '#ffffff', '#000000', '#ffff00', '#00ffff', '#ff00ff'];
        // --- NEW: Audio Engine ---
        let audioCtx = null;
        let audioOscillator = null;
        function playTone() {
            if (!document.getElementById('audio-toggle').checked) return;
            if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
            // Randomize pitch slightly for feedback
            const freq = Math.random() * (800 - 400) + 400;
            const osc = audioCtx.createOscillator();
            const gain = audioCtx.createGain();
            osc.type = 'square'; // Harsh tone
            osc.frequency.setValueAtTime(freq, audioCtx.currentTime);
            // Very short beep
            gain.gain.setValueAtTime(0.05, audioCtx.currentTime);
            gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.05);
            osc.connect(gain);
            gain.connect(audioCtx.destination);
            osc.start();
            osc.stop(audioCtx.currentTime + 0.05);
        }
        function stopToneEngine() {
            // Nothing to do here since tones are fired per frame, but kept for logic structure
        }
        // --- Strobe Logic ---
        function startStatic(color) {
            const layer = document.getElementById('full-screen-layer');
            layer.style.background = color;
            layer.style.display = 'block';
            enterFullScreen(layer);
        }
        function startStrobe(mode) {
            const speedInput = document.getElementById('strobe-speed').value;
            const speed = 110 - parseInt(speedInput); // Map range to ms delay
            if (mode === 'full') {
                const layer = document.getElementById('full-screen-layer');
                layer.style.display = 'block';
                enterFullScreen(layer);
                clearInterval(intervalId);
                intervalId = setInterval(() => {
                    layer.style.background = colors[Math.floor(Math.random() * colors.length)];
                    playTone();
                }, speed);
            }
        }
        function toggleBoxMode() {
            const box = document.getElementById('strobe-box');
            const btn = document.getElementById('box-btn');
            if (isBoxMode) {
                // Turn Off
                isBoxMode = false;
                box.style.display = 'none';
                clearInterval(intervalId);
                btn.classList.remove('active');
                btn.innerHTML = `<svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 8V4m0 0h4M4 4l5 5m11-1V4m0 0h-4m4 0l-5 5M4 16v4m0 0h4m-4 0l5-5m11 5l-5-5m5 5v-4m0 4h-4"></path></svg> Deploy Targeted Box`;
            } else {
                // Turn On
                isBoxMode = true;
                box.style.display = 'block';
                updateBoxSize(); // Apply current slider size
                const speedInput = document.getElementById('strobe-speed').value;
                const speed = 110 - parseInt(speedInput);
                clearInterval(intervalId);
                intervalId = setInterval(() => {
                    box.style.background = colors[Math.floor(Math.random() * colors.length)];
                    playTone();
                }, speed);
                btn.classList.add('active');
                btn.innerHTML = `Stop Box Mode`;
                showToast("Drag box over the stuck pixel area.");
            }
        }
        // --- Live Updaters ---
        function updateStrobeSpeed() {
            // Only update live if a strobe is currently running
            if (document.getElementById('full-screen-layer').style.display === 'block') {
                startStrobe('full');
            } else if (isBoxMode) {
                // restart interval for box
                const speedInput = document.getElementById('strobe-speed').value;
                const speed = 110 - parseInt(speedInput);
                clearInterval(intervalId);
                intervalId = setInterval(() => {
                    document.getElementById('strobe-box').style.background = colors[Math.floor(Math.random() * colors.length)];
                    playTone();
                }, speed);
            }
        }
        function updateBoxSize() {
            const size = document.getElementById('box-size').value;
            const box = document.getElementById('strobe-box');
            box.style.width = `${size}px`;
            box.style.height = `${size}px`;
        }
        // --- Screen & Drag Handling ---
        function enterFullScreen(el) {
            if (el.requestFullscreen) el.requestFullscreen();
            else if (el.webkitRequestFullscreen) el.webkitRequestFullscreen();
            else if (el.msRequestFullscreen) el.msRequestFullscreen();
        }
        function exitFullScreen() {
            const layer = document.getElementById('full-screen-layer');
            layer.style.display = 'none';
            clearInterval(intervalId);
            if (document.fullscreenElement) {
                document.exitFullscreen();
            }
        }
        // Draggable Logic for the Box
        const box = document.getElementById('strobe-box');
        let isDragging = false;
        let currentX, currentY, initialX, initialY;
        let xOffset = 0, yOffset = 0;
        box.addEventListener("mousedown", dragStart);
        document.addEventListener("mouseup", dragEnd);
        document.addEventListener("mousemove", drag);
        box.addEventListener("touchstart", (e) => dragStart(e.touches[0]), { passive: false });
        document.addEventListener("touchend", dragEnd);
        document.addEventListener("touchmove", (e) => {
            if (isDragging) e.preventDefault(); // Prevent scrolling while dragging
            drag(e.touches[0]);
        }, { passive: false });
        function dragStart(e) {
            initialX = e.clientX - xOffset;
            initialY = e.clientY - yOffset;
            if (e.target === box) isDragging = true;
        }
        function dragEnd() {
            initialX = currentX;
            initialY = currentY;
            isDragging = false;
        }
        function drag(e) {
            if (isDragging) {
                currentX = e.clientX - initialX;
                currentY = e.clientY - initialY;
                xOffset = currentX;
                yOffset = currentY;
                setTranslate(currentX, currentY, box);
            }
        }
        function setTranslate(xPos, yPos, el) {
            // Using transform for smooth performance
            el.style.transform = `translate(calc(-50% + ${xPos}px), calc(-50% + ${yPos}px))`;
        }
        function showToast(msg) {
            const toast = document.createElement('div');
            toast.className = "fixed top-24 left-1/2 -translate-x-1/2 bg-slate-800 text-white px-8 py-3 rounded-full shadow-2xl z-[100] animate-bounce font-black text-xs uppercase tracking-widest";
            toast.innerText = msg;
            document.body.appendChild(toast);
            setTimeout(() => toast.remove(), 4000);
        }
        document.addEventListener('keydown', (e) => {
            if (e.key === "Escape") exitFullScreen();
        });
